function stopwatch(limit) {
  let n = 0
  const id = setInterval(() => {
    n++
    console.log(`${n} s`)
    if (n === limit) {
      clearInterval(id)
      console.log(`Stopped at ${limit} s`)
    }
  }, 20)
}

function debounce(fn, ms) {
  let timer
  return (...args) => {
    clearTimeout(timer)
    timer = setTimeout(() => fn(...args), ms)
  }
}

function trafficLight(cycles) {
  const colours = ["green", "amber", "red"]
  let step = 0
  const id = setInterval(() => {
    console.log(colours[step % 3])
    step++
    if (step === cycles * 3) clearInterval(id)
  }, 30)
}

