function loadScore(name) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (name in SCORES) resolve(SCORES[name])
      else reject(new Error(`No player called ${name}`))
    }, 10)
  })
}
async function report(names) {
  const found = {}
  const missing = []
  for (const name of names) {
    try {
      found[name] = await loadScore(name)
    } catch {
      missing.push(name)
    }
  }
  return { found, missing }
}

