async function twoAtATime(items, task) {
  const results = []
  let next = 0
  async function worker() {
    while (next < items.length) {
      const i = next++
      results[i] = await task(items[i])
    }
  }
  await Promise.all([worker(), worker()])
  return results
}

async function findFirst(items, test) {
