async function getJson(url) {
  const response = await fakeFetch(url)
  if (!response.ok) throw new Error(`${url} failed with ${response.status}`)
  return response.json()
}
async function summary(cities) {
  const results = await Promise.allSettled(cities.map((c) => getJson(`/weather/${c}`)))
  const reports = results.filter((r) => r.status === "fulfilled").map((r) => r.value)
  if (reports.length === 0) return null
  const sorted = reports.toSorted((a, b) => a.temp - b.temp)
  const average = reports.reduce((sum, r) => sum + r.temp, 0) / reports.length
  return { warmest: sorted.at(-1).city, coldest: sorted[0].city, average: Math.round(average * 10) / 10 }
}

