function makeCache(maxAge) {
  const saved = new Map()
  return async function get(city) {
    const hit = saved.get(city)
    if (hit && Date.now() - hit.at < maxAge) return hit.report
    const report = await getJson(`/weather/${city}`)
    saved.set(city, { report, at: Date.now() })
    return report
  }
}

